mapper.update:
UPDATE rental_order
SET
  order_status='accepted',
  accept_status='accepted',
  accepted_at=#{now},
  version=version+1,
  updated_at=#{now}
WHERE id=#{id}
  AND version=#{version}
  AND order_status='pending_accept'
  AND accept_status='pending_accept'
  AND accept_deadline_at>#{now}

UPDATE rental_order_delivery
SET
  delivery_status='cancelled',
  updated_at=#{now}
WHERE rental_order_id=#{id}
  AND delivery_status='pending_outbound'

UPDATE rental_order_freight_account
SET
  freight_status=CASE WHEN initial_prepaid_amount_fen>refunded_amount_fen THEN 'refunding' ELSE 'cancelled' END,
  updated_at=#{now}
WHERE rental_order_id=#{id}

UPDATE order_transport_leg l JOIN rental_order o ON o.id=l.rental_order_id
SET l.leg_status='ready',l.updated_at=#{now}
WHERE l.rental_order_id=#{orderId} AND o.order_status='accepted' AND l.leg_status='selected'
